"""The kit's Java adapter (#25): tests/fixtures/adapters/maven.toml, generated by ci-doctor's setup mode (its header
names the run), a test fixture and no built-in, runs Java end to end through the CLI (cli.main in this process) on the
Maven/JUnit 5 fixture repo it was generated for (tests/fixtures/java: base/, and one head per case laid over it): R2,
R1, R4, R3 through PIT, and R0's static and runtime halves. The same behaviours the hand-written adapter it replaced was
held to (#22), each asserted as the generated file gives it, and the five Java gaps of #23 (composed annotations, a
file-activated profile, @SuppressWarnings, assumptions, @Nested), each caught or pinned as the limit its header names.

The real toolchain (mvn and a JDK; Maven Central for the first run) gives the real runner's output: no stub stands in.
A machine without it reads `n/a` (env), never pass, and no test is skipped: each asserts what this machine must give
(the pattern of test_r0_runtime_builtins). The no-JDK cases hide mvn from PATH, or point JAVA_HOME at no JDK, and run
everywhere. R0's runtime half runs only on the stack's target OS (linux): elsewhere it is n/a, named."""
import json
import os
import shutil
import subprocess
import tempfile
import unittest
from unittest import mock

import _kit
from scripts.mech_review import adapter_file, r0_runtime

FIXTURES = os.path.join(_kit.ROOT, "tests", "fixtures")
MAVEN = os.path.join(FIXTURES, "adapters", "maven.toml")
REPO = os.path.join(FIXTURES, "java")
CASES = ("r2", "red", "weak", "broken")
TEST = "src/test/java/com/example/CalcTest.java"
CALC = "src/main/java/com/example/Calc.java"
GENERATED_BLOB = "89b00929edb219317e848b735ae4eb5672c6d274"  # .ekit/adapters/maven.toml of the setup run's commit
SKIPPED = "disabled (@Disabled, or a conditional @Disabled*/@Enabled* marker)"


def toolchain():
    """mvn on PATH, and a JDK it starts with (`mvn --version` exits 0)."""
    mvn = shutil.which("mvn")
    return bool(mvn) and subprocess.run([mvn, "--version"], capture_output=True).returncode == 0


TOOLCHAIN = toolchain()
LINUX = r0_runtime.host_os() == "linux"


def copy_tree(src, dst):
    for top, _, files in os.walk(src):
        for fn in files:
            full = os.path.join(top, fn)
            out = os.path.join(dst, os.path.relpath(full, src))
            os.makedirs(os.path.dirname(out), exist_ok=True)
            shutil.copyfile(full, out)


class Fixture(unittest.TestCase):
    """the fixture repo: `main` holds base/, a branch per case holds its head (the case's files over base/)."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.tmp = tmp.name
        self.repo = os.path.join(self.tmp, "repo")
        copy_tree(os.path.join(REPO, "base"), self.repo)
        self.git("init", "-q", "-b", "main")
        self.commit("base")
        for case in CASES:
            self.git("checkout", "-q", "-b", case, "main")
            copy_tree(os.path.join(REPO, case), self.repo)
            self.commit(case)
        self.git("checkout", "-q", "main")

    def git(self, *args):
        return subprocess.run(["git", "-C", self.repo, "-c", "user.name=t", "-c", "user.email=t@t", "-c",
                               "commit.gpgsign=false", *args], check=True, capture_output=True, text=True).stdout

    def commit(self, msg):
        self.git("add", "-A")
        self.git("commit", "-qm", msg)

    def cli(self, check, head, *extra, rc=(0, 1)):
        r = _kit.run_cli([check, "--repo", self.repo, "--base", "main", "--head", head, "--stack", "maven",
                          "--adapter", MAVEN, "--test-paths", "src/test/**", *extra])
        self.assertIn(r.returncode, rc, r.stderr + r.stdout)
        return json.loads(r.stdout)

    def branch(self, name, start, files):
        """a branch from start with files ({path: text}, or {path: (old, new)} to replace in the file there)."""
        self.git("checkout", "-q", "-b", name, start)
        for path, text in files.items():
            full = os.path.join(self.repo, path)
            if isinstance(text, tuple):
                with open(full) as f:
                    old = f.read()
                self.assertIn(text[0], old)
                text = old.replace(*text)
            os.makedirs(os.path.dirname(full), exist_ok=True)
            with open(full, "w") as f:
                f.write(text)
        self.commit(name)
        self.git("checkout", "-q", "main")
        return name

    def red(self, head, *extra):
        return self.cli("red", head, "--head-branch", "claude/t25", *extra)

    def check_env(self, check):
        self.assertEqual(check["status"], "n/a", check)
        self.assertIn("(env)", check["note"], check)


def ents(env, check):
    return [(e["severity"], e["file"], e["line"], e["problem"]) for e in env["entries"] if e["check"] == check]


class Generated(unittest.TestCase):
    def test_it_is_the_generated_file_marked_a_test_fixture_and_names_linux_and_its_commands(self):
        with open(MAVEN, encoding="utf-8") as f:
            provenance, body = f.read().split("\n\n", 1)
        self.assertTrue(provenance.startswith("# TEST FIXTURE, NOT A SUPPORTED BUILT-IN, AND NOT HAND-WRITTEN:"))
        self.assertIn("generated by ci-doctor's\n# setup mode (skills/ci-doctor/setup.md) on 2026-11-27", provenance)
        blob = subprocess.run(["git", "hash-object", "--stdin"], input=body.encode("utf-8"), capture_output=True,
                              check=True).stdout.decode().strip()
        self.assertEqual(blob, GENERATED_BLOB)  # below the provenance block: the setup run's file, byte for byte
        a = adapter_file.load(MAVEN)
        self.assertEqual((a.name, a.target_os, a.manifests), ("maven", "linux", ("pom.xml",)))
        self.assertEqual(a.commands, {"install": "", "build": "mvn -B -ntp test-compile", "lint": "",
                                      "test": "mvn -B -ntp test"})
        # one test by name: surefire's regex filter, the method's first letter a wildcard (the header's first limit)
        self.assertEqual(a.test_argv(a.commands["test"], TEST, "CalcTest.adds"),
                         ["mvn", "-B", "-ntp", "test", "-Dtest=%regex[(.*/)?CalcTest.class#.dds]"])
        self.assertEqual(a.test_argv(a.commands["test"], TEST, "CalcTest.Signs.negates"),
                         ["mvn", "-B", "-ntp", "test", "-Dtest=%regex[(.*/)?CalcTest.Signs.class#.egates]"])
        self.assertFalse(os.path.exists(os.path.join(_kit.ROOT, "scripts", "mech_review", "adapters", "maven.toml")))
        # PIT is not pinned in the adapter: the pom's plugin version runs, and the pom is mutation config (a person's
        # call on any edit, the version's too)
        self.assertIn("org.pitest:pitest-maven:mutationCoverage", a.mutation_tool["args"])
        self.assertEqual(a.mutation_config("pom.xml", None), "the Maven build's test or PIT config (surefire, "
                         "profiles, PIT, JUnit Platform)")
        with open(os.path.join(REPO, "base", "pom.xml"), encoding="utf-8") as f:
            self.assertIn("<artifactId>pitest-maven</artifactId>\n        <version>1.17.4</version>", f.read())

    def test_its_r0_fixtures_are_the_generated_ones(self):
        """maven.r0/ as the working tree holds it, hashed as git hashes a tree: the setup run's commit's tree"""
        with tempfile.TemporaryDirectory() as tmp:
            env = dict(os.environ, GIT_INDEX_FILE=os.path.join(tmp, "index"))
            git = ["git", "-C", _kit.ROOT, "-c", "core.autocrlf=false"]
            subprocess.run([*git, "add", "-f", "tests/fixtures/adapters/maven.r0"], env=env, check=True)
            tree = subprocess.run([*git, "write-tree", "--prefix=tests/fixtures/adapters/maven.r0/"], env=env,
                                  capture_output=True, text=True, check=True).stdout.strip()
        self.assertEqual(tree, "f0d19a1e857387fd26ca42e1cef4793627eee475")


