class NoJdk(Fixture):
    """without a JDK the result is n/a (env), never a pass: mvn not on PATH, or mvn with JAVA_HOME at no JDK."""

    def no_mvn(self):
        bin_ = os.path.join(self.tmp, "bin")
        os.makedirs(bin_)
        os.symlink(shutil.which("git"), os.path.join(bin_, "git"))
        return mock.patch.dict(os.environ, {"PATH": bin_})

    def test_no_mvn_on_path(self):
        with self.no_mvn():
            red = self.red("red", "--r0", os.path.join(self.tmp, "r0"))
            mut = self.cli("mutants", "weak", "--r0", os.path.join(self.tmp, "r0"))
        for c in ("R1", "R4"):
            self.assertEqual(red["checks"][c]["status"], "n/a", red["checks"][c])
            self.assertTrue(red["checks"][c]["note"].startswith("toolchain absent: `mvn` not found (env)"), red["checks"][c])
        self.assertEqual(mut["checks"]["R3"]["note"], "pitest not installed (env): `mvn` not runnable "
                                                     "(mutation.tool.command); install it (setup-command) or set mutants-cmd")
        self.assertEqual(ents(red, "R1") + ents(red, "R4") + ents(mut, "R3"), [])
        for env in (red, mut):
            self.assertEqual(env["checks"]["R0"]["status"], "n/a", env["checks"]["R0"])

    def test_java_home_at_no_jdk(self):
        with mock.patch.dict(os.environ, {"JAVA_HOME": os.path.join(self.tmp, "no-jdk")}):
            red = self.red("red")
        for c in ("R1", "R4"):
            self.check_env(red["checks"][c])
        if shutil.which("mvn"):
            self.assertIn("JAVA_HOME environment variable is not defined correctly", red["checks"]["R1"]["note"])


class RoundOneR2(Fixture):
    """the cheats R2 had to name on the hand-written adapter's review rounds (#22), on this one."""

    def test_a_condition_annotation_is_a_skip(self):  # B4
        head = self.branch("cond", "main", {TEST: ("    @Test\n    void subtracts", "    @Test\n    @DisabledOnOs(OS.LINUX)\n"
                                                   "    void subtracts")})
        head = self.branch("cond2", head, {TEST: ("    @Test\n    void negates", "    @Test\n    @EnabledOnOs(OS.WINDOWS)\n"
                                                  "    void negates")})
        self.assertEqual([(s, p) for s, _, _, p in ents(self.cli("r2", head), "R2")], [
            ("fail", f"test `CalcTest.subtracts` {SKIPPED}"), ("fail", f"test `CalcTest.negates` {SKIPPED}")])

    def test_pit_config_in_the_pom_and_a_skip_annotation_are_named(self):  # B3
        pom = ("<artifactId>pitest-maven</artifactId>\n        <version>1.17.4</version>\n",
               "<artifactId>pitest-maven</artifactId>\n        <version>1.17.4</version>\n        <configuration>\n"
               "          <excludedMethods>\n            <param>mul</param>\n          </excludedMethods>\n"
               "        </configuration>\n")
        head = self.branch("hide", "weak", {"pom.xml": pom, CALC: ("    public static int mul(", "    @DoNotMutate\n"
                                                                   "    public static int mul(")})
        got = [(e["severity"], e["class"], e["file"], e["problem"]) for e in self.cli("r2", head)["entries"]]
        self.assertEqual(got, [
            ("fail", "needs-human", "pom.xml", "mutation config changed: the Maven build's test or PIT config "
                                               "(surefire, profiles, PIT, JUnit Platform) in pom.xml"),
            ("fail", "needs-human", CALC, "mutation skip added: `@DoNotMutate` hides this code from R3")])

    def test_a_spaced_or_commented_marker_is_still_a_skip(self):  # round 2, B1
        head = self.branch("spaced", "main", {TEST: ("    @Test\n    void subtracts", "    @ /* later */ Disabled\n"
                                                     "    @Test\n    void subtracts")})
        head = self.branch("escaped", head, {TEST: ("    @Test\n    void negates", "    @Test \\u0040Disabled\n    void negates")})
        self.assertEqual([(s, p) for s, _, _, p in ents(self.cli("r2", head), "R2")], [
            ("fail", f"test `CalcTest.subtracts` {SKIPPED}"), ("fail", f"test `CalcTest.negates` {SKIPPED}")])

    def test_an_escaped_line_break_cannot_move_a_marker_off_its_line(self):  # #22 final, the reviewer's repro
        """ten escaped line breaks on the class line put `@DoNotMutate` (raw line 16) ten lines down for the compiler:
        R2 read it off the diff's added lines and gave nothing. The file is now unparseable: R2's needs-human fail."""
        nl = "\\u000a" * 10
        head = self.branch("shifted", "weak", {CALC: ("public final class Calc {", "public final class Calc { // c" + nl)})
        head = self.branch("shifted2", head, {CALC: ("    public static int mul(", "    @DoNotMutate\n    public static int mul(")})
        got = [(e["severity"], e["class"], e["file"], e["problem"]) for e in self.cli("r2", head)["entries"]]
        self.assertIn(("fail", "needs-human", CALC, "file does not parse: a unicode escape decodes to a line break: the "
                       "file's lines are not the compiler's (line 3)"), got)

    def test_an_escaped_line_break_cannot_hide_a_bare_suppression(self):  # #22 final
        nl = "\\u000a" * 10
        head = self.branch("nopmd", "main", {CALC: ("public final class Calc {", "public final class Calc { // c" + nl)})
        head = self.branch("nopmd2", head, {CALC: ("        return a + b;", "        return a + b; // NOPMD")})
        got = [(e["severity"], e["class"], e["file"]) for e in self.cli("r2", head)["entries"]]
        self.assertIn(("fail", "needs-human", CALC), got)

    def test_maven_config_and_suffix_named_skip_annotations_are_named(self):  # round 2, B2 and B4
        head = self.branch("mvncfg", "weak", {".mvn/maven.config": "-DexcludedMethods=mul\n",
                                              ".mvn/jvm.config": "-Dx=y\n", ".mvn/extensions.xml": "<extensions/>\n",
                                              CALC: ("    public static int mul(", "    @ MyGenerated\n"
                                                     "    public static int mul(")})
        got = sorted((e["file"], e["class"]) for e in self.cli("r2", head)["entries"])
        self.assertEqual(got, [(".mvn/extensions.xml", "needs-human"), (".mvn/jvm.config", "needs-human"),
                               (".mvn/maven.config", "needs-human"), (CALC, "needs-human")])

    def test_all_with_the_adapter_proves_it_with_its_fixtures(self):  # S8
        c = self.cli("all", "main", "--head-branch", "claude/t25")["checks"]["R0"]
        self.assertEqual((c["status"], c["note"]), ("pass", "static half: 17 of 17 cases proved"), c)


class JavaGaps(Fixture):
    """#23's Java gaps (the owner's comment there): each one R2 catches through this adapter, or the limit its header
    names, pinned so a regenerated adapter that changes it is seen."""

    def test_a_composed_skip_is_a_named_limit_and_a_composed_test_marker_reads_as_removed(self):
        wip = "package com.example;\n\nimport org.junit.jupiter.api.Disabled;\n\n@Disabled\n@interface Wip {\n}\n"
        head = self.branch("wip", "main", {"src/test/java/com/example/Wip.java": wip,
                                           TEST: ("    @Test\n    void subtracts", "    @Test\n    @Wip\n    void subtracts")})
        self.assertEqual(ents(self.cli("r2", head), "R2"), [])  # limit: markers are matched by word, not resolved
        check = "package com.example;\n\nimport org.junit.jupiter.api.Test;\n\n@Test\n@interface Check {\n}\n"
        head = self.branch("check", "main", {"src/test/java/com/example/Check.java": check,
                                             TEST: ("    @Test\n    void subtracts", "    @Check\n    void subtracts")})
        self.assertEqual([(s, p) for s, _, _, p in ents(self.cli("r2", head), "R2")],
                         [("fail", "test fn `CalcTest.subtracts` removed")])

    def test_a_file_activated_profile_in_the_pom_needs_a_person_and_its_trigger_alone_is_a_limit(self):
        profile = ("  </build>\n", "  </build>\n  <profiles>\n    <profile>\n      <id>quick</id>\n      <activation>\n"
                   "        <file>\n          <exists>.skip-tests</exists>\n        </file>\n      </activation>\n"
                   "      <properties>\n        <skipTests>true</skipTests>\n      </properties>\n    </profile>\n"
                   "  </profiles>\n")
        head = self.branch("profile", "main", {"pom.xml": profile, ".skip-tests": ""})
        self.assertEqual([(e["class"], e["file"]) for e in self.cli("r2", head)["entries"]], [("needs-human", "pom.xml")])
        self.git("checkout", "-q", "-b", "profiled", "main")
        self.git("merge", "-q", "--ff-only", "profile")
        self.git("rm", "-q", ".skip-tests")
        self.commit("the profile on the base, its trigger gone")
        head = self.branch("trigger", "profiled", {".skip-tests": ""})
        r = _kit.run_cli(["r2", "--repo", self.repo, "--base", "profiled", "--head", head, "--stack", "maven",
                          "--adapter", MAVEN, "--test-paths", "src/test/**"])
        self.assertEqual(json.loads(r.stdout)["entries"], [])  # limit: the base's own profile, turned on by a file

    def test_suppress_warnings_is_a_named_limit_and_a_bare_comment_suppression_is_a_fail(self):
        head = self.branch("sw", "main", {TEST: ("    @Test\n    void subtracts", "    @Test\n"
                                                 "    @SuppressWarnings(\"unchecked\")\n    void subtracts"),
                                          CALC: ("public final class Calc {", "@SuppressWarnings(\"all\")\n"
                                                 "public final class Calc {")})
        self.assertEqual(self.cli("r2", head)["entries"], [])  # limit: [[suppressions]] reads comments only
        head = self.branch("nosonar", "main", {CALC: ("        return a + b;", "        return a + b; // NOSONAR")})
        self.assertEqual([(e["severity"], e["file"], e["problem"]) for e in self.cli("r2", head)["entries"]],
                         [("fail", CALC, "`NOSONAR` added without a reason")])

    def test_an_assumption_is_no_r2_entry_and_r4_reads_the_test_as_not_run(self):
        imp = ("import static org.junit.jupiter.api.Assertions.assertTrue;\n",
               "import static org.junit.jupiter.api.Assertions.assertTrue;\n"
               "import static org.junit.jupiter.api.Assumptions.assumeTrue;\n")
        body = ("        int x = Calc.add(1, 2);\n", "        assumeTrue(false);\n        int x = Calc.add(1, 2);\n")
        self.git("checkout", "-q", "-b", "assume", "main")
        with open(os.path.join(self.repo, TEST)) as f:
            text = f.read()
        with open(os.path.join(self.repo, TEST), "w") as f:
            f.write(text.replace(*imp).replace(*body))
        self.commit("assume")
        self.git("checkout", "-q", "main")
        self.assertEqual(self.cli("r2", "assume")["entries"], [])  # limit: a body that keeps its asserts
        env = self.red("assume")
        if not TOOLCHAIN:
            return self.check_env(env["checks"]["R4"])
        self.assertEqual([(s, p) for s, _, _, p in ents(env, "R4")], [("fail", "test `CalcTest.adds` did not run at head")])

    def test_a_nested_test_is_named_with_its_class_skipped_with_it_and_runs_by_name(self):
        nested = ("    @Test\n    void negates() {\n        assertEquals(-2, Calc.neg(2));\n    }\n",
                  "    @Nested\n    class Signs {\n        @Test\n        void negates() {\n"
                  "            assertEquals(-2, Calc.neg(2));\n        }\n    }\n")
        imp = ("import org.junit.jupiter.api.Test;\n", "import org.junit.jupiter.api.Nested;\nimport org.junit.jupiter.api.Test;\n")
        self.git("checkout", "-q", "-b", "nested", "main")
        with open(os.path.join(self.repo, TEST)) as f:
            text = f.read()
        with open(os.path.join(self.repo, TEST), "w") as f:
            f.write(text.replace(*nested).replace(*imp))
        self.commit("nested")
        self.git("checkout", "-q", "main")
        self.assertEqual(ents(self.cli("r2", "nested"), "R2"), [])  # moved into Signs with its asserts: a rename
        head = self.branch("nested-off", "nested", {TEST: ("    @Nested\n", "    @Nested\n    @Disabled\n")})
        r = _kit.run_cli(["r2", "--repo", self.repo, "--base", "nested", "--head", head, "--stack", "maven",
                          "--adapter", MAVEN, "--test-paths", "src/test/**"])
        self.assertEqual([e["problem"] for e in json.loads(r.stdout)["entries"]], [f"test `CalcTest.Signs.negates` {SKIPPED}"])
        a = adapter_file.load(MAVEN)
        with open(os.path.join(REPO, "base", TEST)) as f:
            files = {TEST: f.read().replace(*nested).replace(*imp)}
        found = r0_runtime.found_tests(a, files)
        self.assertIn("CalcTest.Signs.negates", found[TEST])
        # the census: surefire prints the nested class as `Outer$Inner`, the listing's separator `$`
        listing = ("[INFO] com.example.CalcTest$Signs.negates -- Time elapsed: 0.01 s\n"
                   "[INFO] com.example.CalcTest.adds -- Time elapsed: 0.01 s\n")
        listed = a.listed(0, listing, ".")
        c = r0_runtime.census(a, listed, found)
        self.assertEqual((c.found, c.listed, c.misses), (2, 2, []), listed)
        env = self.red("nested")
        if not TOOLCHAIN:
            return self.check_env(env["checks"]["R4"])
        self.assertEqual(env["checks"]["R4"], {"status": "pass", "note": "1 new or changed test(s) run 5x at head"})


class Run(Fixture):
    """R1 and R4 through [run]: surefire's -Dtest=%regex[...], read from its counts."""

    def test_a_new_test_red_on_the_base_passes_r1_and_r4(self):
        env = self.red("red")
        if not TOOLCHAIN:
            return [self.check_env(env["checks"][c]) for c in ("R1", "R4")]
        self.assertEqual({c: env["checks"][c] for c in ("R1", "R4")}, {
            "R1": {"status": "pass", "note": "1 of 1 new or changed test(s) fail on the base's production code "
                                             "(1 compile-red)"},
            "R4": {"status": "pass", "note": "1 new or changed test(s) run 5x at head"}})

    def test_a_guard_test_fails_r1_and_a_test_red_at_head_fails_r4(self):
        env = self.red("broken")
        if not TOOLCHAIN:
            return [self.check_env(env["checks"][c]) for c in ("R1", "R4")]
        self.assertEqual(ents(env, "R1"), [("fail", TEST, 27, "no new or changed test fails without this PR's "
                                                          "production change: `CalcTest.addsOnes` pass on the base's "
                                                          "code too")])
        self.assertEqual(ents(env, "R4"), [("fail", TEST, 27, "test `CalcTest.addsOnes` failed 5 of 5 runs at head "
                                                          "(fail)")])

    def test_a_failing_test_that_prints_the_jdk_message_is_still_a_fail(self):  # B2
        say = ('        System.out.println("The JAVA_HOME environment variable is not defined correctly");\n'
               '        System.out.println("JAVA_HOME not found");\n')
